class FaultTogglingHistoryViewPanel(ViewPanel):
    _SAVE_TOGGLING_ALARMS_BUTTON_XPATH = ('//div[contains(@ng-if, "togglingAlarms")]'
                                          '//ui-button[@a-text="Save" or @a-title="Save"]//button')

    def __init__(self, driver, download_checker):
        super(FaultTogglingHistoryViewPanel, self).__init__(driver)
        self.common_actions = {
            "save_fault_toggling_history": partial(AlarmsCommonAction(driver, download_checker).save_alarms,
                                                   self._SAVE_TOGGLING_ALARMS_BUTTON_XPATH)
        }
        self.__dict__.update(self.common_actions)
